#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cmath>
#include <numbers>
#include <iostream>
#include <stdexcept>
void check(bool ok,const QString& text){if(!ok)throw std::runtime_error(text.toStdString());}
void near(double a,double b){check(std::abs(a-b)<1e-5,QString("Intersect volume mismatch: %1 expected %2").arg(a,0,'g',15).arg(b,0,'g',15));}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument doc;const auto owner=doc.authored()["documentId"].toString();
 auto rectangle=[&](double x1,double x2){auto s=SketchGeometry::addRectangle(SketchGeometry::newFeature(owner,"XY"),{{"u1Mm",x1},{"v1Mm",0},{"u2Mm",x2},{"v2Mm",20}});check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),s),"Rectangle").isEmpty(),"rectangle");return s;};
 auto base=rectangle(0,20);check(doc.commit(CadDocument::extrusionCandidate(doc.authored(),{{"sketchId",base["id"]},{"profileId",doc.sketches().back().profiles[0].profileId},{"distanceMm",10}}),"Stock").isEmpty(),"stock");const auto stock=doc.bodies()[0];
 const auto cap=stock.supportFaces[0];auto circle=SketchGeometry::addCircle(SketchGeometry::newSupportedFeature(owner,{{"producerFeatureId",cap.producerFeatureId},{"bodyId",cap.bodyId},{"faceId",cap.faceId}},"Overlap"),{{"centerUMm",10},{"centerVMm",10},{"diameterMm",10}});const auto entity=circle["parameters"].toObject()["entities"].toArray()[0].toObject();
 auto solve=SketchGeometry::addConstraint(circle,{{"type","fixed"},{"pointIds",QJsonArray{entity["centerPointId"]}}});check(solve.ok,solve.error);circle=solve.feature;solve=SketchGeometry::addDimension(circle,{{"kind","diameter"},{"entityId",entity["id"]},{"valueMm",10}});check(solve.ok,solve.error);circle=solve.feature;const auto dimension=circle["parameters"].toObject()["dimensions"].toArray()[0].toObject()["id"];
 check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),circle),"Circle").isEmpty(),"circle");const auto before=doc.authored();const auto count=doc.history().count();QJsonObject args{{"sketchId",circle["id"]},{"profileId",doc.sketches().back().profiles[0].profileId},{"distanceMm",-6},{"operation","intersect"},{"targetBodyIds",QJsonArray{stock.bodyId}}};
 auto commit=[&](const QJsonObject& a){auto error=doc.commit(CadDocument::extrusionCandidate(doc.authored(),a),"Intersect");check(error.isEmpty(),error);};commit(args);const auto feature=doc.authored()["features"].toArray().last().toObject();const auto full=doc.authored();check(doc.history().count()==count+1 && !feature.contains("bodyId") && doc.bodies().size()==1,"one modifier, no cutter");
 auto inspect=[&](double expected){const auto b=doc.bodies()[0];check(b.bodyId==stock.bodyId && b.featureId==stock.featureId && b.summary["lastModifierFeatureId"]==feature["id"],"retained identities");check(b.summary["valid"].toBool() && b.summary["closed"].toBool(),"closed result");near(b.summary["volumeMm3"].toDouble(),expected);near(b.summary["overlapVolumeMm3"].toDouble(),expected);};inspect(150*std::numbers::pi);
 doc.history().undo();check(doc.authored()==before,"undo");doc.history().redo();check(doc.authored()==full,"redo");args["featureId"]=feature["id"];args["distanceMm"]=-8;commit(args);inspect(200*std::numbers::pi);
 solve=SketchGeometry::updateDimension(circle,{{"dimensionId",dimension},{"valueMm",12}});check(solve.ok,solve.error);check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),solve.feature),"Resize overlap").isEmpty(),"upstream edit");inspect(288*std::numbers::pi);
 const auto stable=doc.authored();const auto revision=doc.revision();const auto history=doc.history().count();args["distanceMm"]=6;check(!doc.commit(CadDocument::extrusionCandidate(stable,args),"Touch-only").isEmpty(),"touch-only must refuse");check(doc.authored()==stable && doc.revision()==revision && doc.history().count()==history,"atomic touch refusal");
 QTemporaryDir dir;check(doc.save(dir.path()+"/intersect.alloy").isEmpty(),"save");CadDocument reopened;check(reopened.open(dir.path()+"/intersect.alloy").isEmpty() && reopened.authored()==stable,"exact reopen");near(reopened.bodies()[0].summary["volumeMm3"].toDouble(),288*std::numbers::pi);
 // Origin sketch full containment is valid with no removed volume.
 CadDocument contained;auto s=SketchGeometry::addRectangle(SketchGeometry::newFeature(contained.authored()["documentId"].toString(),"XY"),{{"u1Mm",0},{"v1Mm",0},{"u2Mm",20},{"v2Mm",20}});check(contained.commit(SketchGeometry::replaceFeature(contained.authored(),s),"Stock").isEmpty(),"contained sketch");const auto pid=contained.sketches()[0].profiles[0].profileId;check(contained.commit(CadDocument::extrusionCandidate(contained.authored(),{{"sketchId",s["id"]},{"profileId",pid},{"distanceMm",10}}),"Stock").isEmpty(),"contained stock");const auto target=contained.bodies()[0].bodyId;
 check(contained.commit(CadDocument::extrusionCandidate(contained.authored(),{{"sketchId",s["id"]},{"profileId",pid},{"distanceMm",20},{"operation","intersect"},{"targetBodyIds",QJsonArray{target}}}),"Containment").isEmpty(),"full containment must pass");near(contained.bodies()[0].summary["volumeMm3"].toDouble(),4000);near(contained.bodies()[0].summary["removedVolumeMm3"].toDouble(),0);
 // Separate prisms leave disconnected overlap: preserve exact target/document.
 auto split=SketchGeometry::addRectangle(SketchGeometry::newFeature(contained.authored()["documentId"].toString(),"XY"),{{"u1Mm",1},{"v1Mm",1},{"u2Mm",3},{"v2Mm",3}});split=SketchGeometry::addRectangle(split,{{"u1Mm",10},{"v1Mm",10},{"u2Mm",12},{"v2Mm",12}});check(contained.commit(SketchGeometry::replaceFeature(contained.authored(),split),"Two regions").isEmpty(),"split sketch");QJsonArray ids;for(const auto& p:contained.sketches().back().profiles)ids.append(p.profileId);const auto untouched=contained.authored();check(!contained.commit(CadDocument::extrusionCandidate(untouched,{{"sketchId",split["id"]},{"profileIds",ids},{"distanceMm",5},{"operation","intersect"},{"targetBodyIds",QJsonArray{target}}}),"Disconnected").isEmpty() && contained.authored()==untouched,"disconnected result refuses atomically");
 auto outside=SketchGeometry::addRectangle(SketchGeometry::newFeature(contained.authored()["documentId"].toString(),"XY"),{{"u1Mm",30},{"v1Mm",30},{"u2Mm",40},{"v2Mm",40}});check(contained.commit(SketchGeometry::replaceFeature(contained.authored(),outside),"Outside").isEmpty(),"outside sketch");const auto noOverlap=contained.authored();check(!contained.commit(CadDocument::extrusionCandidate(noOverlap,{{"sketchId",outside["id"]},{"profileId",contained.sketches().back().profiles[0].profileId},{"distanceMm",5},{"operation","intersect"},{"targetBodyIds",QJsonArray{target}}}),"No overlap").isEmpty() && contained.authored()==noOverlap,"no overlap refuses atomically");
 std::cout<<"PASS: retained Intersect, signed face/origin, analytic volumes, upstream/edit/history/storage, containment and atomic refusals\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
